('ver-1794209611123-v2','dos-1793953890585',2,'{\"full_name\":\"Tran Thi Bao Tran\",\"department\":\"Phòng Hành chính - Tổng hợp\",\"truong_don_vi\":\"PGS.TS. Nguyễn Văn A\",\"phone\":\"0912345678\",\"email\":\"tranthibaotran712@gmail.com\",\"position\":\"Cán bộ / Giảng viên\",\"transfer_location\":\"Tại Trường Đại học Y Dược Cần Thơ\",\"transfer_form\":\"Chuyển giao công nghệ có điều kiện.\",\"transfer_time\":\"Từ tháng 10/2026 đến tháng 12/2026\",\"ten_de_tai\":\"Nghiên cứu ứng dụng kỹ thuật\",\"purpose\":\"Sản phẩm chuyển giao công nghệ là kết quả nghiên cứu khoa học đã được nghiệm thu cấp Trường. Mục đích của kế hoạch là tổ chức chuyển giao, ứng dụng kết quả nghiên cứu vào thực tiễn đào tạo và phục vụ cộng đồng tại Trường Đại học Y Dược Cần Thơ.\",\"receiver_needs\":\"Đơn vị tiếp nhận có nhu cầu cập nhật, bổ sung nội dung khoa học hiện đại vào chương trình đào tạo, phục vụ trực tiếp cho công tác giảng dạy và học tập của sinh viên, học viên.\",\"provider_capacity\":\"Đề tài đã được nghiệm thu cấp Trường. Chủ nhiệm đề tài và nhóm tác giả đủ năng lực chuyên môn, sẵn sàng thực hiện chuyển giao theo đúng kế hoạch.\",\"transfer_goals\":\"Nhằm tăng cường sự hiểu biết của giảng viên và sinh viên về kết quả nghiên cứu mới nhất, đưa vào bài giảng và giáo trình đào tạo, nâng cao tính thực tiễn và tính tin cậy của nội dung giảng dạy.\",\"transfer_target\":\"Kiến thức, số liệu và kết quả khoa học từ đề tài nghiên cứu đã được nghiệm thu, bao gồm tài liệu tham khảo, bài báo khoa học và quy trình kỹ thuật liên quan.\",\"transfer_method\":\"Bàn giao tài liệu kỹ thuật, hướng dẫn trực tiếp vận hành và sử dụng sản phẩm, đào tạo nhân sự tiếp nhận tại cơ sở. Hỗ trợ kỹ thuật trong thời gian 03 tháng sau chuyển giao.\",\"transfer_rights\":\"Chuyển giao quyền sử dụng không độc quyền để đưa vào bài giảng và giáo trình đào tạo tại Trường Đại học Y Dược Cần Thơ. Bên nhận chuyển giao không được chuyển nhượng lại cho bên thứ ba khi chưa có sự đồng ý của tác giả.\",\"attendees\":\"Giảng viên các bộ môn liên quan, sinh viên Y đa khoa năm thứ 3 trở lên, học viên sau đại học chuyên ngành có liên quan.\",\"funding_source\":\"Từ nguồn kinh phí hoạt động khoa học và công nghệ của Trường theo quy chế chi tiêu nội bộ hiện hành.\",\"transfer_date\":\"Bắt đầu triển khai lúc 08 giờ 00 ngày 15/10/2026 (ekip kỹ thuật thiết lập từ 07 giờ 30 đến 11 giờ 30); vận hành thử nghiệm ngày 14/10/2026; bàn giao bộ tài liệu hướng dẫn ngày 16/10/2026.\",\"transfer_cost\":\"Không thu phí chuyển giao. Chi phí phát sinh (nếu có) thực hiện theo quy chế chi tiêu nội bộ của Trường.\",\"ds_danh_gia_rui_ro\":[{\"stt\":1,\"yeu_to_rui_ro\":\"Chậm tiến độ chuyển giao do lịch giảng dạy, khám chữa bệnh dày đặc\",\"p\":2,\"s\":2,\"r\":4,\"phan_loai\":\"Thấp\"},{\"stt\":2,\"yeu_to_rui_ro\":\"Hạ tầng thiết bị, phần mềm tại đơn vị tiếp nhận chưa đồng bộ\",\"p\":2,\"s\":3,\"r\":6,\"phan_loai\":\"Trung bình\"},{\"stt\":3,\"yeu_to_rui_ro\":\"Nhân sự tiếp nhận chuyển giao luân chuyển hoặc chưa thành thạo kỹ thuật\",\"p\":2,\"s\":2,\"r\":4,\"phan_loai\":\"Thấp\"}],\"ds_kiem_soat_rui_ro\":[{\"stt\":1,\"yeu_to_rui_ro\":\"Chậm tiến độ chuyển giao\",\"bien_phap\":\"Lập tiến độ chi tiết theo tuần, phân công nhân sự dự phòng\",\"don_vi_phu_trach\":\"Chủ nhiệm đề tài\",\"don_vi_phoi_hop\":\"Đơn vị tiếp nhận\",\"thoi_gian\":\"Trước và trong đợt chuyển giao\",\"san_pham\":\"Biên bản nghiệm thu đúng hạn\"},{\"stt\":2,\"yeu_to_rui_ro\":\"Hạ tầng chưa đồng bộ\",\"bien_phap\":\"Khảo sát tiền trạm, cấu hình thử nghiệm và nâng cấp thiết bị\",\"don_vi_phu_trach\":\"Bộ phận kỹ thuật\",\"don_vi_phoi_hop\":\"Phòng KH&CN\",\"thoi_gian\":\"Trước khi bàn giao 01 tuần\",\"san_pham\":\"Hệ thống vận hành ổn định\"},{\"stt\":3,\"yeu_to_rui_ro\":\"Nhân sự chưa thành thạo\",\"bien_phap\":\"Tổ chức tập huấn thực hành cầm tay chỉ việc, bàn giao tài liệu chi tiết\",\"don_vi_phu_trach\":\"Nhóm nghiên cứu\",\"don_vi_phoi_hop\":\"Đơn vị tiếp nhận\",\"thoi_gian\":\"Trong suốt kỳ chuyển giao\",\"san_pham\":\"100% nhân sự đạt yêu cầu\"}