  `department_id` varchar(50) DEFAULT NULL,
  `department_name` varchar(150) DEFAULT NULL,
  `status` enum('SUBMITTED','RETURNED_FOR_REVISION','VALIDATED','PENDING_SIGNED_REVIEW','WAITING_RECTOR_SIGNATURE','SIGNED_ARCHIVED','NEW','NEEDS_REVISION','PRECHECK_PASSED','WAITING_FOR_SUBMISSION','FACULTY_SIGNED','SCHOOL_SIGNING','SIGNED','COMPLETED') NOT NULL DEFAULT 'SUBMITTED',
  `current_version` int(11) NOT NULL DEFAULT 1 COMMENT 'Phiên bản tài liệu hiện tại (v1, v2, v3...)',
  `applicant_email` varchar(150) DEFAULT NULL COMMENT 'Email của Thầy/Cô nộp đơn để gửi Gmail SMTP',
  `form_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Dữ liệu Web Form đã làm sạch (Single Source of Truth)' CHECK (json_valid(`form_data`)),
  `has_workshop` tinyint(1) DEFAULT 0,
  `has_financial_implication` tinyint(1) DEFAULT 0,
  `ten_de_tai` varchar(255) DEFAULT NULL COMMENT 'Tên đề tài nghiên cứu chuyển giao tri thức',
  `truong_don_vi` varchar(150) DEFAULT NULL COMMENT 'Họ tên Trưởng đơn vị',
  `status_1a` varchar(30) DEFAULT 'PENDING' COMMENT 'Trạng thái duyệt 1a: PENDING, APPROVED, RETURNED',
  `status_2a` varchar(30) DEFAULT 'PENDING' COMMENT 'Trạng thái duyệt 2a: PENDING, APPROVED, RETURNED',
  `rejected_target` varchar(20) DEFAULT NULL COMMENT 'Biểu mẫu mục tiêu bị trả về: 1a, 2a, both',
  `rejection_reason_1a` text DEFAULT NULL COMMENT 'Lý do trả về riêng cho Biểu mẫu 1a',
  `rejection_reason_2a` text DEFAULT NULL COMMENT 'Lý do trả về riêng cho Biểu mẫu 2a',
  `form_data_1a` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Dữ liệu biểu mẫu 1a trong bộ hồ sơ kép' CHECK (json_valid(`form_data_1a`)),
  `form_data_2a` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Dữ liệu biểu mẫu 2a trong bộ hồ sơ kép' CHECK (json_valid(`form_data_2a`)),
  `signature_config` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Cấu hình khung chữ ký động (phòng ban, BGH, nơi nhận)' CHECK (json_valid(`signature_config`)),
  `generated_docx_path` varchar(500) DEFAULT NULL COMMENT 'Đường dẫn file Word (.docx) phiên bản mới nhất',
  `generated_pdf_path` varchar(500) DEFAULT NULL COMMENT 'Đường dẫn file PDF (.pdf) phiên bản mới nhất',
  `docx_file_url` varchar(500) DEFAULT NULL,
  `to_trinh_docx_url` varchar(500) DEFAULT NULL,
  `ke_hoach_docx_url` varchar(500) DEFAULT NULL,
  `approved_pdf_path` varchar(500) DEFAULT NULL COMMENT 'File PDF chuẩn chốt khi Admin nhấn Duyệt (VALIDATED)',
  `precheck_pdf_url` varchar(500) DEFAULT NULL,
  `department_signed_files` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Danh sách file PDF đã ký phòng ban + ảnh/PDF minh chứng' CHECK (json_valid(`department_signed_files`)),
  `resubmitted_signed_files` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`resubmitted_signed_files`)),
  `faculty_signed_pdf_url` varchar(500) DEFAULT NULL,
  `evidence_files` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`evidence_files`)),
  `final_signed_pdf_path` varchar(500) DEFAULT NULL COMMENT 'File PDF hoàn tất có chữ ký Hiệu trưởng (SIGNED_ARCHIVED)',
  `final_pdf_url` varchar(500) DEFAULT NULL,
  `revision_note` text DEFAULT NULL COMMENT 'Gợi ý chỗ sai cần sửa chữa của Admin khi Trả về sửa lỗi',
  `review_notes` text DEFAULT NULL,
  `timeline_logs` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Mảng lưu lịch sử chuyển trạng thái và timestamp' CHECK (json_valid(`timeline_logs`)),
  `decision_number` varchar(100) DEFAULT NULL,
  `decision_date` date DEFAULT NULL,
  `khcn_signed` tinyint(1) DEFAULT 0,
  `khcn_signed_at` timestamp NULL DEFAULT NULL,
  `khtc_signed` tinyint(1) DEFAULT 0,
  `khtc_signed_at` timestamp NULL DEFAULT NULL,
  `bgh_signed` tinyint(1) DEFAULT 0,
  `bgh_signed_at` timestamp NULL DEFAULT NULL,
  `drive_folder_url` varchar(500) DEFAULT 'https://drive.google.com/drive/folders/1UZfnO_hY9LshjsaHH6btODtWgii0Vv8-?usp=drive_link',
  `submitted_at` timestamp NULL DEFAULT current_timestamp(),
  `reviewed_at` timestamp NULL DEFAULT NULL,
  `faculty_signed_at` timestamp NULL DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_dossier_code` (`code`),
  KEY `fk_dossier_user` (`user_id`),
  KEY `fk_dossier_tmpl` (`template_id`),
  KEY `fk_dossier_dept` (`department_id`),
  KEY `idx_dossier_status` (`status`),
  CONSTRAINT `fk_dossier_dept` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_dossier_tmpl` FOREIGN KEY (`template_id`) REFERENCES `document_templates` (`id`),
  CONSTRAINT `fk_dossier_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

