chưa thành thạo\",\"bien_phap\":\"Tổ chức tập huấn thực hành cầm tay chỉ việc, bàn giao tài liệu chi tiết\",\"don_vi_phu_trach\":\"Nhóm nghiên cứu\",\"don_vi_phoi_hop\":\"Đơn vị tiếp nhận\",\"thoi_gian\":\"Trong suốt kỳ chuyển giao\",\"san_pham\":\"100% nhân sự đạt yêu cầu\"}],\"purpose\":\"Nhằm đưa kết quả nghiên cứu khoa học vào thực tiễn giảng dạy, góp phần nâng cao chất lượng đào tạo và cập nhật nội dung chương trình học tại Trường Đại học Y Dược Cần Thơ.\",\"authors_group\":\"Bảo Trân Trần\",\"transfer_method\":\"Thông qua bài giảng tích hợp tại Trường có nội dung liên quan và sẽ được đưa vào giáo trình tái bản, kết hợp trao đổi học thuật giữa nhóm tác giả và giảng viên của đơn vị tiếp nhận.\",\"receiving_party\":\"Bệnh viện Trường Đại học Y Dược Cần Thơ (đầu mối: Phòng Kế hoạch tổng hợp) – theo Phiếu đề xuất nhu cầu tiếp nhận chuyển giao công nghệ; người đại diện BS.CKII. Lại Văn Nông.\",\"steering_committee\":\"1. Đại diện Ban Giám Hiệu - Trưởng ban\\n2. Trưởng Phòng KH&CN - Phó Trưởng ban\",\"organizing_committee\":\"1. Trưởng Khoa - Trưởng ban\\n2. Đại diện Bên nhận chuyển giao - Đồng Trưởng ban\\n3. Thư ký Hội thảo - Cán bộ phụ trách KH&CN\",\"implementing_staff\":\"1. Chủ nhiệm đề tài - Phụ trách chung\\n2. Nhóm tác giả - Thực hiện chuyển giao chuyên môn\\n3. Chuyên viên kỹ thuật - Hỗ trợ và vận hành\",\"workshop_chair\":\"1. Đại diện Ban Giám Hiệu - Chủ tọa\\n2. Đại diện Ban Chủ nhiệm Khoa - Đồng Chủ tọa\",\"workshop_speaker\":\"1. Chủ nhiệm đề tài - Báo cáo viên chính\\n2. Thành viên nhóm nghiên cứu - Báo cáo viên lâm sàng\",\"workshop_program\":\"08h00 - 08h30 | Đón tiếp đại biểu, tuyên bố lý do, khai mạc | Ban Tổ chức và đại biểu\\n08h30 - 10h00 | Báo cáo giới thiệu sản phẩm và hướng dẫn kỹ thuật | Nhóm tác giả đề tài\\n10h00 - 11h00 | Thảo luận, thực hành và ký biên bản bàn giao | Toàn thể đại biểu\",\"workshop_assignments\":\"Chuẩn bị nội dung báo cáo và tài liệu kỹ thuật | Nhóm tác giả\\nCông tác hậu cần, hội trường và danh sách đại biểu | Đơn vị tiếp nhận\",\"workshop_budget\":\"Theo quy chế chi tiêu nội bộ của Trường Đại học Y Dược Cần Thơ.\",\"product_name\":\"Nghiên cứu ứng dụng kỹ thuật số\",\"ten_de_tai\":\"Nghiên cứu ứng dụng kỹ thuật số\",\"transfer_form\":\"Chuyển giao công nghệ độc lập.\",\"transfer_time\":\"Từ tháng 10/2026 đến tháng 12/2026\",\"receiver_needs\":\"Đơn vị tiếp nhận có nhu cầu cập nhật, bổ sung nội dung khoa học hiện đại vào chương trình đào tạo, phục vụ trực tiếp cho công tác giảng dạy và học tập của sinh viên, học viên.\",\"provider_capacity\":\"Đề tài đã được nghiệm thu cấp Trường. Chủ nhiệm đề tài và nhóm tác giả đủ năng lực chuyên môn, sẵn sàng thực hiện chuyển giao theo đúng kế hoạch.\",\"transfer_goals\":\"Nhằm tăng cường sự hiểu biết của giảng viên và sinh viên về kết quả nghiên cứu mới nhất, đưa vào bài giảng và giáo trình đào tạo, nâng cao tính thực tiễn và tính tin cậy của nội dung giảng dạy.\",\"transfer_target\":\"Kiến thức, số liệu và kết quả khoa học từ đề tài nghiên cứu đã được nghiệm thu, bao gồm tài liệu tham khảo, bài báo khoa học và quy trình kỹ thuật liên quan.\",\"transfer_rights\":\"Chuyển giao quyền sử dụng không độc quyền để đưa vào bài giảng và giáo trình đào tạo tại Trường Đại học Y Dược Cần Thơ. Bên nhận chuyển giao không được chuyển nhượng lại cho bên thứ ba khi chưa có sự đồng ý của tác giả.\",\"attendees\":\"Giảng viên các bộ môn liên quan, sinh viên Y đa khoa năm thứ 3 trở lên, học viên sau đại học chuyên ngành có liên quan.\",\"funding_source\":\"Từ nguồn kinh phí hoạt động khoa học và công nghệ của Trường theo quy chế chi tiêu nội bộ hiện hành.\"}',0,1,'Nghiên cứu ứng dụng kỹ thuật số','BS.CKII Lại Văn Nông','PENDING','PENDING',NULL,NULL,NULL,'{\"full_name\":\"Bảo Trân Trần\",\"department\":\"Khoa Khoa học Cơ bản\",\"truong_don_vi\":\"BS.CKII Lại Văn Nông\",\"phone\":\"0912345678\",\"email\":\"tranthibaotran712@gmail.com\",\"position\":\"Cán bộ / Giảng viên\",\"transfer_location\":\"Tại Trường Đại học Y Dược Cần Thơ\",\"transfer_form\":\"Chuyển giao công nghệ độc lập.\",\"transfer_time\":\"Từ tháng 10/2026 đến tháng 12/2026\",\"ten_de_tai\":\"Nghiên cứu ứng dụng kỹ thuật số\",\"purpose\":\"Nhằm đưa kết quả nghiên cứu khoa học vào thực tiễn giảng dạy, góp phần nâng cao chất lượng đào tạo và cập nhật nội dung chương trình học tại Trường Đại học Y Dược Cần Thơ.\",\"receiver_needs\":\"Đơn vị tiếp nhận có nhu cầu cập nhật, bổ sung nội dung khoa học hiện đại vào chương trình đào tạo, phục vụ trực tiếp cho công tác giảng dạy và học tập của sinh viên, học viên.\",\"provider_capacity\":\"Đề tài đã được nghiệm thu cấp Trường. Chủ nhiệm đề tài và nhóm tác giả đủ năng lực chuyên môn, sẵn sàng thực hiện chuyển giao theo đúng kế hoạch.\",\"transfer_goals\":\"Nhằm tăng cường sự hiểu biết của giảng viên và sinh viên về kết quả nghiên cứu mới nhất, đưa vào bài giảng và giáo trình đào tạo, nâng cao tính thực tiễn và tính tin cậy của nội dung giảng dạy.\",\"transfer_target\":\"Kiến thức, số liệu và kết quả khoa học từ đề tài nghiên cứu đã được nghiệm thu, bao gồm tài liệu tham khảo, bài báo khoa học và quy trình kỹ thuật liên quan.\",\"transfer_method\":\"Thông qua bài giảng tích hợp tại Trường có nội dung liên quan và sẽ được đưa vào giáo trình tái bản, kết hợp trao đổi học thuật giữa nhóm tác giả và giảng viên của đơn vị tiếp nhận.\",\"transfer_rights\":\"Chuyển giao quyền sử dụng không độc quyền để đưa vào bài giảng và giáo trình đào tạo tại Trường Đại học Y Dược Cần Thơ. Bên nhận chuyển giao không được chuyển nhượng lại cho bên thứ ba khi chưa có sự đồng ý của tác giả.\",\"attendees\":\"Giảng viên các bộ môn liên quan, sinh viên Y đa khoa năm thứ 3 trở lên, học viên sau đại học chuyên ngành có liên quan.\",\"funding_source\":\"Từ nguồn kinh phí hoạt động khoa học và công nghệ của Trường theo quy chế chi tiêu nội bộ hiện hành.\"}','{\"full_name\":\"Bảo Trân Trần\",\"department\":\"Khoa Khoa học Cơ bản\",\"truong_don_vi\":\"BS.CKII Lại Văn Nông\",\"phone\":\"0912345678\",\"email\":\"tranthibaotran712@gmail.com\",\"position\":\"