INSERT INTO `email_notifications` VALUES
('em-1793953891406-912','dos-1793953886984','tranthibaotran.2k@gmail.com','Cô Admin (Phòng KH&CN)','[CTUMP DocuGov] Hồ sơ mới vừa nộp (v1): CGCN-2026-0001 - Kế hoạch tổ chức chuyển giao công nghệ: “Nghiên cứu ứng dụng kỹ thuật”','\n        <div style=\"font-family: Arial, sans-serif; line-height: 1.6; color: #333;\">\n          <h3 style=\"color: #1e3a8a;\">Kính gửi Cô Admin (Phòng KH&CN),</h3>\n          <p>Hệ thống vừa tiếp nhận hồ sơ chuyển giao công nghệ mới do Thầy/Cô <b>Bảo Trân Trần</b> (Phòng Hành chính - Tổng hợp) nộp qua Web Form.</p>\n          <table style=\"border-collapse: collapse; width: 100%; margin: 16px 0;\">\n            <tr><td style=\"padding: 8px; border: 1px solid #ddd; background: #f8fafc; width: 32%;\"><b>Mã hồ sơ:</b></td><td style=\"padding: 8px; border: 1px solid #ddd;\"><b>CGCN-2026-0001</b> (Phiên bản v1)</td></tr>\n            <tr><td style=\"padding: 8px; border: 1px solid #ddd; background: #f8fafc;\"><b>Tên đề tài / nội dung:</b></td><td style=\"padding: 8px; border: 1px solid #ddd;\">Kế hoạch tổ chức chuyển giao công nghệ: “Nghiên cứu ứng dụng kỹ thuật”</td></tr>\n            <tr><td style=\"padding: 8px; border: 1px solid #ddd; background: #f8fafc;\"><b>Người nộp:</b></td><td style=\"padding: 8px; border: 1px solid #ddd;\">Bảo Trân Trần (tranthibaotran712@gmail.com)</td></tr>\n            <tr><td style=\"padding: 8px; border: 1px solid #ddd; background: #f8fafc;\"><b>Trạng thái:</b></td><td style=\"padding: 8px; border: 1px solid #ddd; color: #2563eb; font-weight: bold;\">SUBMITTED (Đã gửi / Chờ duyệt)</td></tr>\n          </table>\n          <p>Kính mời Cô Admin truy cập hệ thống để kiểm tra nội dung, nhấn <b>Duyệt (Hồ sơ hợp lệ)</b> hoặc <b>Yêu cầu trả về (Sửa lỗi)</b>.</p>\n        </div>\n      ','Bước 1 - Gửi đơn mới (v1)','SENT','2026-11-06 08:31:31'),
('em-1793953893640-377','dos-1793953886984','tranthibaotran712@gmail.com','Bảo Trân Trần','[CTUMP DocuGov] Tiếp nhận thành công hồ sơ CGCN-2026-0001 (v1)','\n        <div style=\"font-family: Arial, sans-serif; line-height: 1.6; color: #333;\">\n          <h3 style=\"color: #1e3a8a;\">Kính gửi Thầy/Cô Bảo Trân Trần,</h3>\n          <p>Hồ sơ chuyển giao công nghệ mã <b>CGCN-2026-0001</b> (Phiên bản v1) của Thầy/Cô đã được nộp thành công và đang ở trạng thái <b>Đã gửi / Chờ duyệt</b>.</p>\n          <p>Khi hồ sơ được Cô Admin duyệt hợp lệ, hệ thống sẽ gửi email đính kèm trực tiếp bản PDF chuẩn để Thầy/Cô tải về đi trình ký phòng ban.</p>\n        </div>\n      ','Bước 1 - Xác nhận tiếp nhận','SENT','2026-11-06 08:31:33'),
('em-1793953894619-170','dos-1793953890585','tranthibaotran.2k@gmail.com','Cô Admin (Phòng KH&CN)','[CTUMP DocuGov] Hồ sơ mới vừa nộp (v1): CGCN-2026-0002 - Kế hoạch tổ chức chuyển giao công nghệ: “Nghiên cứu ứng dụng kỹ thuật”','\n        <div style=\"font-family: Arial, sans-serif; line-height: 1.6; color: #333;\">\n          <h3 style=\"color: #1e3a8a;\">Kính gửi Cô Admin (Phòng KH&CN),</h3>\n          <p>Hệ thống vừa tiếp nhận hồ sơ chuyển giao công nghệ mới do Thầy/Cô <b>Bảo Trân Trần</b> (Phòng Hành chính - Tổng hợp) nộp qua Web Form.</p>\n          <table style=\"border-collapse: collapse; width: 100%; margin: 16px 0;\">\n            <tr><td style=\"padding: 8px; border: 1px solid #ddd; background: #f8fafc; width: 32%;\"><b>Mã hồ sơ:</b></td><td style=\"padding: 8px; border: 1px solid #ddd;\"><b>CGCN-2026-0002</b> (Phiên bản v1)</td></tr>\n            <tr><td style=\"padding: 8px; border: 1px solid #ddd; background: #f8fafc;\"><b>Tên đề tài / nội dung:</b></td><td style=\"padding: 8px; border: 1px solid #ddd;\">Kế hoạch tổ chức chuyển giao công nghệ: “Nghiên cứu ứng dụng kỹ thuật”</td></tr>\n            <tr><td style=\"padding: 8px; border: 1px solid #ddd; background: #f8fafc;\"><b>Người nộp:</b></td><td style=\"padding: 8px; border: 1px solid #ddd;\">Bảo Trân Trần (tranthibaotran712@gmail.com)</td></tr>\n            <tr><td style=\"padding: 8px; border: 1px solid #ddd; background: #f8fafc;\"><b>Trạng thái:</b></td><td style=\"padding: 8px; border: 1px solid #ddd; color: #2563eb; font-weight: bold;\">SUBMITTED (Đã gửi / Chờ duyệt)</td></tr>\n          </table>\n          <p>Kính mời Cô Admin truy cập hệ thống để kiểm tra nội dung, nhấn <b>Duyệt (Hồ sơ hợp lệ)</b> hoặc <b>Yêu cầu trả về (Sửa lỗi)</b>.</p>\n        </div>\n      ','Bước 1 - Gửi đơn mới (v1)','SENT','2026-11-06 08:31:34'),
('em-1793953897090-787','dos-1793953890585','tranthibaotran712@gmail.com','Bảo Trân Trần','[CTUMP DocuGov] Tiếp nhận thành công hồ sơ CGCN-2026-0002 (v1)','\n        <div style=\"font-family: Arial, sans-serif; line-height: 1.6; color: #333;\">\n          <h3 style=\"color: #1e3a8a;\">Kính gửi Thầy/Cô Bảo Trân Trần,</h3>\n          <p>Hồ sơ chuyển giao công nghệ mã <b>CGCN-2026-0002</b> (Phiên bản v1) của Thầy/Cô đã được nộp thành công và đang ở trạng thái <b>Đã gửi / Chờ duyệt</b>.</p>\n          <p>Khi hồ sơ được Cô Admin duyệt hợp lệ, hệ thống sẽ gửi email đính kèm trực tiếp bản PDF chuẩn để Thầy/Cô tải về đi trình ký phòng ban.</p>\n        </div>\n      ','Bước 1 - Xác nhận tiếp nhận','SENT','2026-11-06 08:31:37'),
('em-1793954081768-776','dos-1793953890585','tranthibaotran712@gmail.com','Bảo Trân Trần','[CTUMP DocuGov] Hồ sơ CGCN-2026-0002 trả về sửa lỗi - Có gợi ý chỉnh sửa từ Admin','\n        <div style=\"font-family: Arial, sans-serif; line-height: 1.6; color: #333;\">\n          <h3 style=\"color: #b91c1c;\">Kính gửi Thầy/Cô Bảo Trân Trần,</h3>\n          <p>Hồ sơ mã <b>CGCN-2026-0002</b> (Phiên bản v1) đã được Cô Admin kiểm tra và chuyển sang trạng thái <b>Trả về sửa lỗi (RETURNED_FOR_REVISION)</b>.</p>\n          <div style=\"background: #fef2f2; border-left: 4px solid #ef4444; padding: 14px; margin: 16px 0; color: #991b1b;\">\n            <b>Gợi ý chỗ sai cần sửa chữa của Cô Admin:</b><br/>\n            <div style=\"margin-top: 6px; white-space: pre-line;\">Kính nhờ quý thầy cô chỉnh sửa những nội dung sau: sửa tên và tên đề tài</div>\n          </div>\n          <p>Thầy/Cô vui lòng truy cập màn hình <b>Chi tiết đơn (CGCN-2026-0002)</b> trên hệ thống, bấm <b>\"Chỉnh sửa lại\"</b> để sửa trực tiếp trên Web Form và nhấn <b>\"Nộp lại\"</b>. Hệ thống sẽ tự động kết xuất lại bộ file Word và PDF phiên bản mới nhất.</p>\n        </div>\n      ','Bước 2A [Luồng False] - Trả về sửa lỗi','SENT','2026-11-06 08:34:41'),
('em-1794209614286-810','dos-1793953890585','tranthibaotran.2k@gmail.com','Cô Admin (Phòng KH&CN)','[CTUMP DocuGov] Hồ sơ CGCN-2026-0002 đã sửa và nộp lại (Phiên bản v2)','\n        <div style=\"font-family: Arial, sans-serif; line-height: 1.6; color: #333;\">\n          <h3 style=\"color: #1e3a8a;\">Kính gửi Cô Admin (Phòng KH&CN),</h3>\n          <p>Thầy/Cô <b>Bảo Trân Trần</b> vừa hoàn tất chỉnh sửa và <b>Nộp lại</b> hồ sơ mã <b>CGCN-2026-0002</b> (<b>Phiên bản v2</b>).</p>\n          <p>Hệ thống đã tự động xóa bản nháp cũ và kết xuất lại bộ file Word (.docx) và PDF (.pdf) phiên bản <b>v2</b> khớp 100% với dữ liệu mới. Kính mời Cô Admin vào kiểm tra và xét duyệt lại.</p>\n        </div>\n      ','Bước 2B [Luồng False] - Nộp lại (v2)','SENT','2026-11-09 07:33:34'),
