('em-1794278437385-201','dos-1794213593976','tranthibaotran712@gmail.com','Bảo Trân Trần','[CTUMP DocuGov] Hồ sơ CGCN-2026-0005: Yêu cầu chỉnh sửa Biểu mẫu 2a (Kế hoạch)','\n        <div style=\"font-family: Arial, sans-serif; line-height: 1.6; color: #333;\">\n          <h3 style=\"color: #b91c1c;\">Kính gửi Thầy/Cô Bảo Trân Trần,</h3>\n          <p>Hồ sơ mã <b>CGCN-2026-0005</b> (Phiên bản v1) có yêu cầu chỉnh sửa đối với <b>Biểu mẫu 2a (Kế hoạch)</b>.</p>\n          <div style=\"background: #fef2f2; border-left: 4px solid #ef4444; padding: 14px; margin: 16px 0; color: #991b1b;\">\n            <b>Gợi ý chỉnh sửa từ Cô Admin (Biểu mẫu 2a (Kế hoạch)):</b><br/>\n            <div style=\"margin-top: 6px; white-space: pre-line;\">sửa tên giúp mình</div>\n          </div>\n          <p>Thầy/Cô vui lòng truy cập hệ thống để cập nhật và nộp lại <b>Biểu mẫu 2a (Kế hoạch)</b>.</p>\n        </div>\n      ','Bước 2A [Luồng False] - Trả về Biểu mẫu 2a (Kế hoạch)','SENT','2026-11-10 02:40:37'),
('em-1794278531354-338','dos-1794213593976','tranthibaotran712@gmail.com','Bảo Trân Trần','[CTUMP DocuGov] Hồ sơ CGCN-2026-0005 (v2) ĐÃ ĐƯỢC DUYỆT - Kèm file PDF chuẩn đi trình ký','\n        <div style=\"font-family: Arial, sans-serif; line-height: 1.6; color: #333;\">\n          <h3 style=\"color: #1e3a8a;\">Kính gửi Thầy/Cô Bảo Trân Trần,</h3>\n          <p>Hồ sơ CGCN mã <b>CGCN-2026-0005</b> (<b>Phiên bản v2</b>) đã được Cô Admin xét duyệt <b>ĐÃ HỢP LỆ (VALIDATED)</b>.</p>\n          <p>File PDF chuẩn của phiên bản <b>v2</b> (khớp 100% với nội dung Thầy/Cô đã kê khai/chỉnh sửa) được <b>đính kèm trực tiếp trong email này</b>.</p>\n          <div style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 12px; margin: 16px 0;\">\n            <b>Hướng dẫn bước tiếp theo:</b>\n            <ol style=\"margin: 8px 0 0 16px; padding: 0;\">\n              <li>Tải file PDF chuẩn đính kèm trong email (hoặc bấm nút <b>\"Tải file PDF chuẩn\"</b> trên trang Chi tiết đơn).</li>\n              <li>Đem trình ký Lãnh đạo Khoa / Phòng ban.</li>\n              <li>Sau khi có chữ ký phòng ban, vào khung thao tác bên phải trên trang Chi tiết đơn để <b>Upload lại file đã ký + minh chứng</b>.</li>\n            </ol>\n          </div>\n        </div>\n      ','Bước 3 - Duyệt hợp lệ & Gửi PDF (v2)','SENT','2026-11-10 02:42:11'),
('em-1794279683309-566','dos-1794213590633','tranthibaotran712@gmail.com','Bảo Trân Trần','[CTUMP DocuGov] Hồ sơ CGCN-2026-0004: Yêu cầu chỉnh sửa Biểu mẫu 1a (Tờ trình)','\n        <div style=\"font-family: Arial, sans-serif; line-height: 1.6; color: #333;\">\n          <h3 style=\"color: #b91c1c;\">Kính gửi Thầy/Cô Bảo Trân Trần,</h3>\n          <p>Hồ sơ mã <b>CGCN-2026-0004</b> (Phiên bản v1) có yêu cầu chỉnh sửa đối với <b>Biểu mẫu 1a (Tờ trình)</b>.</p>\n          <div style=\"background: #fef2f2; border-left: 4px solid #ef4444; padding: 14px; margin: 16px 0; color: #991b1b;\">\n            <b>Gợi ý chỉnh sửa từ Cô Admin (Biểu mẫu 1a (Tờ trình)):</b><br/>\n            <div style=\"margin-top: 6px; white-space: pre-line;\">thầy cô hãy chỉnh sửa  mục đích nội dung sao cho hợp lí</div>\n          </div>\n          <p>Thầy/Cô vui lòng truy cập hệ thống để cập nhật và nộp lại <b>Biểu mẫu 1a (Tờ trình)</b>.</p>\n        </div>\n      ','Bước 2A [Luồng False] - Trả về Biểu mẫu 1a (Tờ trình)','SENT','2026-11-10 03:01:23'),
('em-1794279820441-772','dos-1794213590633','tranthibaotran.2k@gmail.com','Cô Admin (Phòng KH&CN)','[CTUMP DocuGov] Hồ sơ CGCN-2026-0004: Đã nộp lại Biểu mẫu 1a (Phiên bản v2)','\n        <div style=\"font-family: Arial, sans-serif; line-height: 1.6; color: #333;\">\n          <h3 style=\"color: #1e3a8a;\">Kính gửi Cô Admin (Phòng KH&CN),</h3>\n          <p>Thầy/Cô <b>Bảo Trân Trần</b> vừa hoàn tất chỉnh sửa và <b>Nộp lại Biểu mẫu 1a (Tờ trình)</b> cho hồ sơ mã <b>CGCN-2026-0004</b> (<b>Phiên bản v2</b>).</p>\n          <p>Biểu mẫu 2a được giữ nguyên phiên bản đã nộp trước đó. Kính mời Cô Admin vào kiểm tra và xét duyệt.</p>\n        </div>\n      ','Bước 2B - Nộp lại Biểu mẫu 1a (v2)','SENT','2026-11-10 03:03:40'),
('em-1794281969373-675','dos-1794213593976','tranthibaotran.2k@gmail.com','Cô Admin (Phòng KH&CN)','[CTUMP DocuGov] Thầy/Cô đã upload bản ký phòng ban: CGCN-2026-0005 - Chờ duyệt','\n        <div style=\"font-family: Arial, sans-serif; line-height: 1.6; color: #333;\">\n          <h3 style=\"color: #1e3a8a;\">Kính gửi Cô Admin (Phòng KH&CN),</h3>\n          <p>Thầy/Cô <b>Bảo Trân Trần</b> vừa tải lên <b>bản PDF đã có chữ ký phòng ban</b> và <b>2 tệp minh chứng</b> cho hồ sơ mã <b>CGCN-2026-0005</b>.</p>\n          <p>Trạng thái hiện tại: <b style=\"color: #d97706;\">PENDING_SIGNED_REVIEW (Chờ duyệt)</b>.</p>\n          <p>Kính mời Cô Admin kiểm tra file ký phòng ban và nhấn nút <b>\"Chuyển sang Chờ ký Hiệu trưởng\"</b>.</p>\n        </div>\n      ','Bước 4 - Upload bản ký phòng ban (Chờ duyệt)','SENT','2026-11-10 03:39:29');
